"""Every on-screen text/graphic event of 'Human Heart and Circulation', absolute seconds (from ../out/heart/timing.json,
the measured narration) and 720p positions. Built-in kinds are drawn by overlay.py (label, title, card, pill, callout,
anchor_text, outro); the project kinds (table6, apill, pill2, measure, trace, cyclebar, gauge, counter, markers, loop,
toggle, bigtext) by overlay_ext.py. Colours are the palette's 8-bit twins so the overlay matches the 3D semantic colours."""
import os, json
from projects.heart import palette as P

E = []
def add(kind, t0, t1, **kw): E.append(dict(kind=kind, t0=t0, t1=t1, **kw))

_TP = os.path.dirname(os.path.abspath(__file__))
_T = json.load(open(next(q for q in (os.path.join(_TP, 'timing.json'), os.path.join(_TP, '..', '..', '..', 'out', 'heart', 'timing.json')) if os.path.exists(q))))   # the project-local copy rides in the Modal mount (out/ does not)
SECS = _T['sections']
def mmss(t): t = int(round(t)); return f'{t // 60:02d}:{t % 60:02d}'
TOPICS = [(s['title'], f"{mmss(s['t0'])} - {mmss(s['t1'])}") for s in SECS]

OXY, DEOXY, GOLD, CYAN, O2, CO2, NUT, WASTE, DANGER = P.LABEL_OXY, P.LABEL_DEOXY, P.LABEL_GOLD, P.LABEL_CYAN, P.LABEL_O2, P.LABEL_CO2, P.LABEL_NUTRIENT, P.LABEL_WASTE, P.LABEL_DANGER
WHITE = (255, 255, 255); FILL = P.PILL_FILL; BONE = P.LABEL_BONE; LUNG = P.LABEL_LUNG; MUS = P.LABEL_MUSCLE

def apill(t0, t1, name, text, dx=110, dy=-40, color=WHITE, border=None, size=15, leader=True, fill=FILL):
    add('apill', t0, t1, name=name, text=text, dx=dx, dy=dy, color=color, border=border or color, size=size, leader=leader, fill=fill)

# ================================================================= intro (0-30.48)
