add('title', 4.5, 30.48, text='Complete Chapter', y=110, size=24)
add('table6', 6.0, 30.48, topics=TOPICS)
add('pill2', 5.4, 12.6, text='72 beats every minute', x=200, y=640, fill=FILL, border=OXY, color=OXY, size=17)
add('pill2', 14.2, 17.0, text='Under the skin', x=260, y=600, fill=FILL, border=P.LABEL_BONE, color=WHITE, size=16)
